// PATTERN: the factory is a thin SYNC seam — NO new logic, NO try/catch, NO async.
// (spec/01 §1, spec/11 §8 Step 8; mirrors the oracle minus the settings loader.)
export default function (pi: ExtensionAPI): void {
  setLogFile(getConfig().log.file);          // getConfig() lazily caches DEFAULT_CONFIG on first call
  pi.registerTool(makeRewindTool(pi));        // FACTORY: captures pi via closure
  pi.registerTool(makeShrinkTool(pi));
  pi.registerTool(makeCheckpointTool(pi));
  pi.registerTool(auditTool);                 // CONST: read-only, no pi
  pi.on("context", contextHandler);           // INLINE: filter.ts exports the handler directly
  registerBloatReminder(pi);                  // SEAM:   pi.on("tool_result", …)
  registerTurnEndMetric(pi);                  // SEAM:   pi.on("turn_end", …)
  pi.on("session_start", (_e, ctx) => {        // C12: read sessionId FRESH inside the callback
    resetRuntime(ctx.sessionManager.getSessionId());
  });
  pi.on("session_shutdown", () => { clearAll(); });
}

// PATTERN (test): hand-rolled fake pi capturing registerTool + on (mirror test/tools/rewind.test.ts makePi).
// Do NOT use the real Pi. Capture into arrays/maps and assert on them. Reset module config via
// setConfig(undefined) in afterEach so the disabled-config test cannot leak into siblings.
